 * @param props - {@link NavbarProps}
 */
const Navbar = ({
    onLogoPress,
    navItems,
    searchPlaceholder,
    shortcutLabel,
    onSearchPress,
    languages,
    activeLocale,
    onLocaleChange,
    isDarkMode,
    onThemeToggle,
    cartCount,
    onCartPress,
    notifications,
