import React from "react"
import { cn } from "@heroui/react"
import {
    BookmarkSimpleIcon,
    ChartBarIcon,
    CreditCardIcon,
    DesktopIcon,
    GraduationCapIcon,
    PaintBrushIcon,
    PencilSimpleIcon,
    ShieldCheckIcon,
    SlidersHorizontalIcon,
    StarIcon,
    WalletIcon,
} from "@phosphor-icons/react"
import { Divider } from "@/components/atoms/display/Divider"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { CollapsibleSidebar } from "@/components/blocks/navigation/CollapsibleSidebar"
import { DesktopNavRow } from "./DesktopNavRow"

/**
 * `SettingsSidebarNav` ΓÇö the account-settings destination list, drawn as a
 * collapsible desktop rail and, below `@app-md`, a sticky horizontal pill bar.
 * Two structural leaves ΓÇö `DesktopRail` (collapsible `Link`-shaped rows with a
 * divider between groups) and `MobilePillBar` (a flattened rounded-full chip
 * row). Both render the same component; only the container width differs, so
 * each story shows the branch its own `@app-md` query resolves to. `activeHref`
 * is data, so within each leaf it is a state.
 *
 * Held: sticky-under-navbar desktop height host, mobile sticky pill surface, and
 * active/inactive chip `cn` ΓÇö no existing frame/composite owns those shapes
 * (`ShowFrom`/`HideAbove` lack sticky+height; `NavigationRail` owns column fill;
 * `RailShell` sticky uses `top-24`, not `top-16`).
 */

/** Every account-settings destination this rail can offer ΓÇö the closed vocabulary the block owns. */
export type SettingsDestinationKey =
    | "editProfile"
    | "appearance"
    | "security"
    | "sessions"
    | "courseHistory"
    | "aiSettings"
    | "aiSubscription"
    | "aiUsage"
    | "bookmarks"
    | "membership"
    | "installments"

/** One settings destination ΓÇö TYPED DOMAIN DATA only: which one, and where it navigates. */
export interface SettingsNavItem {
    /** Which destination this row is ΓÇö drives its icon + label (block-owned table below). */
    key: SettingsDestinationKey
    /** Absolute href the row navigates to. */
    href: string
}

/**
 * A cluster of destinations rendered together. No `label` field: every real group is
 * unlabelled (see `src`'s `getSettingsGroups` ΓÇö only a divider separates them), so adding
 * an unused caption prop would be inventing a case no screen asks for (┬º14d.3).
 */
export interface SettingsNavGroup {
    /** Stable React key for the group ΓÇö not shown, only used for reconciliation + the divider count. */
    key: string
    /** The destinations in this group, in display order. */
    items: Array<SettingsNavItem>
}

/** Destination ΓåÆ label. The block's own wording (┬º14d.1), never handed in by the caller. */
export const DESTINATION_LABEL: Record<SettingsDestinationKey, string> = {
    editProfile: "Edit profile",
    appearance: "Appearance",
    security: "Security",
    sessions: "Login sessions",
    courseHistory: "Learning history",
    aiSettings: "AI settings",
    aiSubscription: "AI plan",
    aiUsage: "AI usage",
    bookmarks: "Saved",
    membership: "Membership plan",
    installments: "Installments",
}

/** Destination ΓåÆ icon. Same glyphs `src`'s `nav.tsx` maps, so porting this table reads as ONE control. */
export const DESTINATION_ICON: Record<SettingsDestinationKey, TypographyIcon> = {
    editProfile: PencilSimpleIcon,
    appearance: PaintBrushIcon,
    security: ShieldCheckIcon,
    sessions: DesktopIcon,
    courseHistory: GraduationCapIcon,
    aiSettings: SlidersHorizontalIcon,
    aiSubscription: CreditCardIcon,
    aiUsage: ChartBarIcon,
    bookmarks: BookmarkSimpleIcon,
    membership: StarIcon,
    installments: WalletIcon,
}

/** Props for {@link SettingsSidebarNav}. */
export interface SettingsSidebarNavProps {
    /** Grouped destinations, in display order. */
    groups: Array<SettingsNavGroup>
    /** Which destination's `href` is being viewed right now. */
    activeHref: string
    /** Fired with a destination's `href` when its row/pill is pressed. */
    onNavigate: (href: string) => void
    /** Heading shown atop the desktop rail (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /** `localStorage` key the collapsed flag persists under, so the choice survives navigation. */
    storageKey: string
    /** Accessible name for the mobile pill nav landmark. Defaults to {@link title}. */
    mobileNavAriaLabel?: string
}

/**
 * The settings destination rail. See the file header for the reused `CollapsibleSidebar`
 * gap, the two still-inlined gaps, the enum-owned vocabulary, the `@app-md` port, and the
 * two structural leaves.
 *
 * @param props - {@link SettingsSidebarNavProps}
 */
const SettingsSidebarNav = ({
    groups,
    activeHref,
    onNavigate,
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    mobileNavAriaLabel,
}: SettingsSidebarNavProps) => {
    // Mobile leaf flattens every group into one scroll strip ΓÇö grouping only matters to the
    // desktop rail's dividers, the mobile bar has no room to spare on a section caption.
    const flatItems = groups.flatMap((group) => group.items)

    return (
        <StackV
            identity={{ tier: "block", component: "SettingsSidebarNav" }}
            gap={1}
            principle="group-boundary"
            explain="Separates the desktop rail from the mobile pill bar so each leaf keeps its own seam owner ΓÇö not sibling-stack, because these are alternate structural leaves rather than repeating peers."
            items={[
                () => (
                    // Held: sticky-under-navbar + viewport-minus-chrome height ΓÇö no named frame.
                    <div className="hidden shrink-0 @app-md:sticky @app-md:top-16 @app-md:block @app-md:h-[calc(100dvh-4rem)]">
                        <CollapsibleSidebar
                            title={title}
                            collapseLabel={collapseLabel}
                            expandLabel={expandLabel}
                            storageKey={storageKey}
                            className="h-full"
                        >
                            {groups.map((group, index) => (
                                <React.Fragment key={group.key}>
                                    {index > 0 ? <Divider /> : null}
                                    <StackV
                                        gap={1}
                                        principle="sibling-stack"
                                        explain="Same-kind peer stack of settings rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                        items={group.items.map((item) => () => (
                                            <DesktopNavRow
                                                item={item}
                                                isActive={item.href === activeHref}
                                                onNavigate={onNavigate}
                                            />
                                        ))}
                                    />
                                </React.Fragment>
                            ))}
                        </CollapsibleSidebar>
                    </div>
                ),
                () => (
                    // Held: mobile sticky pill landmark + chip active/inactive cn.
                    <nav aria-label={mobileNavAriaLabel ?? title} className="sticky top-16 z-30 @app-md:hidden">
                        <div className="overflow-x-auto border-b border-default bg-background/80 backdrop-blur-xl">
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                padding={{ x: 4, y: 3 }}
                                items={flatItems.map((item) => () => {
                                    const isActive = item.href === activeHref
                                    const Icon = DESTINATION_ICON[item.key]
                                    return (
                                        <button
                                            type="button"
                                            aria-current={isActive ? "page" : undefined}
                                            onClick={() => onNavigate(item.href)}
                                            className={cn(
                                                "shrink-0 rounded-full border px-3 py-2 transition-colors",
                                                isActive ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                            )}
                                        >
                                            <StackH
                                                principle="icon-text"
                                                explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                items={[
                                                    () => <Icon aria-hidden focusable="false" className="size-4 shrink-0" />,
                                                    () => <Typography size="sm" text={DESTINATION_LABEL[item.key]} noWrap />,
                                                ]}
                                            />
                                        </button>
                                    )
                                })}
                            />
                        </div>
                    </nav>
                ),
            ]}
        />
    )
}

export { SettingsSidebarNav }

"use client"

import React from "react"
import { useRouter } from "@/i18n/navigation"
import { InlineLink } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/** A single footer link: an internal `path` (locale-aware push) OR an external
 *  `href` (mailto / off-site) ΓÇö exactly one is set. */
export interface FooterNavLink {
    /** Stable React key. */
    key: string
    /** Visible label. */
    label: string
    /** Internal route, locale-aware ΓÇö pushed through the i18n router. */
    path?: string
    /** External / mailto href ΓÇö rendered as a plain anchor press. */
    href?: string
}

/** Props for {@link FooterNavColumn}. */
export interface FooterNavColumnProps {
    /** Quiet column heading (e.g. "Explore", "Support"). */
    title: string
    /** Links stacked under the heading. */
    links: ReadonlyArray<FooterNavLink>
}

/**
 * FooterNavColumn ΓÇö one quiet column of the global {@link Footer}: a small muted
 * heading over a vertical stack of links. Internal links (`path`) route through
 * the locale-aware router; external / mailto links (`href`) open via `onPress`.
 *
 * Kept as a layout helper for callers that still want the connected column
 * shape; the live {@link Footer} now composes the starci `FooterLinkColumn`.
 */
export const FooterNavColumn = ({
    title,
    links,
}: FooterNavColumnProps) => {
    const router = useRouter()

    const rows = links.map((link) => () => (
        <InlineLink
            key={link.key}
            label={link.label}
            size="sm"
            onPress={() => {
                if (link.href) {
                    window.location.href = link.href
                    return
                }
                if (link.path) {
                    router.push(link.path)
                }
            }}
        />
    ))

    return (
        <StackV
            identity={{ tier: "layout", component: "FooterNavColumn" }}
            gap={4}
            principle="label-field"
            explain="Column title over its link list ΓÇö not title-subtitle, because the title names the group of controls below rather than continuing in one voice."
            items={[
                () => <Typography size="sm" weight="bold" text={title} />,
                () => (
                    <StackV
                        gap={2}
                        principle="sibling-stack"
                        explain="Same-kind peer stack of link rows ΓÇö not group-boundary, because these are repeating siblings rather than section groups."
                        items={rows}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"
import { ShowFrom } from "@/components/frames/ShowFrom"
import { StackH } from "@/components/frames/Stack"
import { useRouter } from "@/i18n/navigation"
import { useNavbarItems } from "../useNavbarItems"

/**
 * Props for {@link NavLinks}.
 */
export type NavLinksProps = Record<string, never>

/**
 * Desktop navbar link group (hidden on small screens).
 *
 * Container: derives its entries + active-route state from the router/locale
 * itself and self-navigates on press. `"use client"` for the hooks + press
 * handlers. `ShowFrom` owns the md visibility switch; `ButtonRadioGroup` owns
 * the pill row (same vocabulary as the starci `Navbar` / `NavLinks` block).
 */
export const NavLinks = () => {
    const router = useRouter()
    const items = useNavbarItems()
    const activePath = items.find((item) => item.isActive)?.path ?? ""

    return (
        <StackH
            identity={{ tier: "layout", component: "NavLinks" }}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <ShowFrom
                        at="md"
                        body={() => (
                            <ButtonRadioGroup
                                items={items.map((item) => ({
                                    value: item.path,
                                    content: <Typography size="sm" text={item.label} />,
                                }))}
                                value={activePath}
                                onChange={(path) => router.push(path)}
                                ariaLabel="Main navigation"
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}
